func readBatchRenameMapping(path string) (map[string]string, error) {
	if path == "" {
		return nil, usageErr(fmt.Errorf("mapping file is required"))
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	if strings.EqualFold(filepath.Ext(path), ".json") {
		var mapping map[string]string
		if err := json.Unmarshal(data, &mapping); err != nil {
			return nil, fmt.Errorf("parsing JSON mapping: %w", err)
		}
		clean := map[string]string{}
		for id, title := range mapping {
			id = strings.TrimSpace(id)
			title = strings.TrimSpace(title)
			if id != "" && title != "" {
				clean[id] = title
			}
		}
		return clean, nil
	}

	reader := csv.NewReader(strings.NewReader(string(data)))
	rows, err := reader.ReadAll()
	if err != nil {
		return nil, fmt.Errorf("parsing CSV mapping: %w", err)
	}
	if len(rows) == 0 {
		return map[string]string{}, nil
	}
	header := map[string]int{}
	for i, name := range rows[0] {
		header[strings.TrimSpace(name)] = i
	}
	idCol, okID := header["recording_id"]
	titleCol, okTitle := header["title"]
	if !okID || !okTitle {
		return nil, usageErr(fmt.Errorf("CSV mapping must contain recording_id and title columns"))
	}
	mapping := map[string]string{}
	for _, row := range rows[1:] {
		if idCol >= len(row) || titleCol >= len(row) {
			continue
		}
		id := strings.TrimSpace(row[idCol])
		title := strings.TrimSpace(row[titleCol])
		if id != "" && title != "" {
			mapping[id] = title
		}
	}
	return mapping, nil
}

